/** Everything the mail reads, as the page loads it; a read that failed is null and named in `gaps`. */
export type MondaySheetReads = {
  data: BridgeData
  fin: DashboardFinancials | null
  bank: MercuryCash | null
  vectorInputs: BridgeVectorInputs | null
  weeksInputs: VectorDaysInputs | null
  buildInputs: BuildPaceInput | null
  billJobs: BillPileJob[] | null
  demandInputs: DemandInput | null
  calls: BridgeCall[] | null
  collectReads: CollectDeskReads | null
  /** What could not be read, in plain words for the mail's last line; empty when everything came back. */
  gaps: string[]
}

/** What the mail takes besides the reads; the weekly send reads each from the database as the page does. */
export type WeekMailOptions = {
  /** The accounts the owner left out of cash on hand (`bridge_cash_accounts_out_v1`); none when absent. */
  accountsOut?: ReadonlyArray<string>
  /** Each account's name in Mercury, by its id, for the sentence that says what is left out. */
  bankNames?: ReadonlyMap<string, string>
  /** The Done presses people made on the calls' moves (`parseMoveMarks`). */
  marks?: ReadonlyArray<MoveMark>
}

/** "Oct 24", from a company-calendar day. */
export const md = (ymd: string): string => new Date(`${ymd}T12:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' })
/** A bill with no pay history at all is expected this many days out. */
export const DEFAULT_PAY_DAYS = 45
/** Sub labor owed is expected to go out this many days from today. */
export const SUB_LABOR_DEFAULT_DAYS = 14

const addDays = (ymd: string, days: number): string => new Date(Date.parse(`${ymd}T00:00:00Z`) + days * 86_400_000).toISOString().slice(0, 10)

export type Receipt = CashEvent & { source: string; basis: ReceiptBasis }
export type Doubtful = { label: string; usd: number; daysLate: number }
export type CollectDeskState = { pile: CollectPile; cut: CollectPayerCut }

/** The Collect desk (punch list #177): the pile by each payer's own pace, once its three reads are in. */
export function buildCollectDeskFrom(fin: DashboardFinancials | null, data: BridgeData, reads: CollectDeskReads | null): CollectDeskState | null {
  if (!fin || !reads) return null
  const bills = collectBillsFromAr({ ar: fin.ar.items, collections: fin.arCollections.items, sentByInvoice: reads.sentByInvoice })
  // The GC pace here rests on the GC payers in the pile, the ones we are collecting from now, not on every small GC on record.
  const gcPaceFromIds = new Set(bills.map((b) => b.payerId).filter((id): id is string => !!id && reads.gcPayerIds.has(id)))
  const pile = buildCollectPile({ bills, paySpeeds: data.paySpeeds, promisesByJob: data.promisedByJob, payAppJobIds: reads.payAppJobIds, gcPayerIds: reads.gcPayerIds, gcPaceFromIds, todayYmd: data.todayYmd })
  return { pile, cut: buildCollectPayers(pile, { touches: reads.touches }) }
}

/**
 * Receipts: each open AR item on its expected day — promise → the payer's own median → the GC pace here → the segment
 * median → the company median (since v2.6034 the model reads the pile's order) → 45 days. Recently
 * late lands within its own pace from today (v2.5219), so late invoices spread instead of piling on one day; late past
 * the doubtful line is not counted (listed with collections). Since v2.5857 a bill the Collect desk's pile has read
 * takes the pile's expected day.
 */
export function buildReceipts(input: { data: BridgeData; fin: DashboardFinancials | null; collectDesk: CollectDeskState | null }): { receipts: Receipt[]; doubtful: Doubtful[] } {
  const { data, fin, collectDesk } = input
  if (!fin) return { receipts: [], doubtful: [] }
  const out: Receipt[] = []
  const doubtful: Doubtful[] = []
  const pileByKey = collectDesk ? new Map(collectDesk.pile.bills.map((b) => [b.key, b])) : null
  for (const item of fin.ar.items) {
    if (item.amount <= 0) continue
    const promise = item.jobId && data.promisedByJob ? data.promisedByJob[item.jobId] : undefined
    const pileBill = pileByKey?.get(item.key)
    const pileRead = pileBill ? collectReceiptFor(pileBill) : null
    // item.dateYmd is already a day: read as an instant it would be midnight UTC, the evening before.
    const model = pileRead ? null : billedExpectedPayModel({ billedAtIso: null, estBillYmd: item.dateYmd, customerId: item.customerId ?? null }, data.paySpeeds, data.todayYmd, promise ?? null)
    let expectedYmd: string
    let source: string
    let basis: ReceiptBasis
    if (pileRead) {
      expectedYmd = pileRead.expectedYmd
      source = pileRead.source
      basis = pileRead.basis
    } else if (model) {
      expectedYmd = model.expectedYmd
      // The pile receipt's words (`collectReceiptFor`), so the band reads the same before and after the pile is in.
      source =
        model.source === 'promised'
          ? 'promised'
          : model.source === 'customer'
            ? `pays in ~${model.medianDays}d`
            : model.source === 'gc'
              ? `the GC pace here ~${model.medianDays}d`
              : model.source === 'segment'
                ? model.paceWords
                : `company pace ~${model.medianDays}d`
      basis = model.source === 'promised' || model.source === 'customer' ? model.source : 'company'
    } else {
      expectedYmd = addDays(item.dateYmd ?? data.todayYmd, DEFAULT_PAY_DAYS)
      source = `no history · ${DEFAULT_PAY_DAYS}d default`
      basis = 'default'
    }
    const pace = pileRead ? pileRead.paceDays : model && model.source !== 'promised' ? model.medianDays : null
    const graceDays = lateWithinDays(pace)
    const sched = scheduleReceipt(expectedYmd, data.todayYmd, { graceDays })
    if (sched.status === 'doubtful') {
      doubtful.push({ label: item.label, usd: item.amount, daysLate: sched.daysLate })
      continue
    }
    out.push({
      ymd: sched.ymd,
      usd: item.amount,
      label: item.label,
      kind: 'receipt',
      source: sched.status === 'late' ? `${sched.daysLate}d late — assumed within ${graceDays}d${pace != null ? ' by their pace' : ''}` : source,
      basis: sched.status === 'late' ? 'late' : basis,
    })
  }
  return { receipts: out.sort((a, b) => (a.ymd < b.ymd ? -1 : a.ymd > b.ymd ? 1 : 0)), doubtful }
}

/** Bills: supply due dates and payroll Fridays from the loader, plus sub labor owed (the finance hook's AP figure) on the default horizon. */
export function buildBills(data: BridgeData, fin: DashboardFinancials | null): Array<{ ymd: string; usd: number; label: string }> {
  const out = [...data.bills]
  const sub = fin?.ap.subLaborTotal ?? 0
  if (sub > 0) out.push({ ymd: addDays(data.todayYmd, SUB_LABOR_DEFAULT_DAYS), usd: sub, label: 'Sub labor owed' })
  return out.sort((a, b) => (a.ymd < b.ymd ? -1 : a.ymd > b.ymd ? 1 : 0))
}

/**
 * The Bridge's first screen as the weekly email: the page's chain from the reads, with no step pressed and nobody
 * signed in. A move the page would propose for whoever is looking carries no person here.
 */
export function buildWeekMailFromReads(reads: MondaySheetReads, opts: WeekMailOptions = {}): WeekMail {
  const { data, fin, bank, vectorInputs, weeksInputs } = reads
  const todayYmd = data.todayYmd
  const weeks = BRIDGE_DAYS_BACK / 7

  // Cash on hand: the bank's accounts the owner counts, or the typed figure rolled through the ledger.
  const accounts = bank ? buildCashAccounts({ bank, names: opts.bankNames ?? new Map<string, string>(), out: opts.accountsOut ?? [] }) : null
  const typedRolled = data.cashSetting ? cashTodayFromAsOf({ cashAsOfUsd: data.cashSetting.usd, asOfYmd: data.cashSetting.asOfYmd, todayYmd, bankFlowByDay: data.bankFlowByDay }) : null
  const cashToday = accounts ? accounts.countedUsd : typedRolled

  const collectDesk = buildCollectDeskFrom(fin, data, reads.collectReads)
  const { receipts, doubtful } = buildReceipts({ data, fin, collectDesk })
  const bills = buildBills(data, fin)
  const forecast =
    cashToday != null
      ? buildCashForecast({ todayYmd, daysAhead: BRIDGE_DAYS_AHEAD, cashTodayUsd: cashToday, floorUsd: data.floorUsd, events: [...bills.map((b) => ({ ymd: b.ymd, usd: b.usd, label: b.label, kind: 'bill' as const })), ...receipts], dailyDrainUsd: data.dailyDrainUsd })
      : null

  const buildPace = reads.buildInputs ? buildBuildPace(reads.buildInputs) : null
  const billPile = reads.billJobs ? buildBillPile({ jobs: reads.billJobs, points: reads.buildInputs?.points ?? [], todayYmd }) : null
  const demand = reads.demandInputs ? buildDemand(reads.demandInputs) : null
  const thisWeek = payWeekContaining(todayYmd)
  const calls: ReadonlyArray<BridgeCall> = reads.calls ?? []
  const thisWeekCall = callForWeek(calls, thisWeek.start)

  // The made tile's weeks: the eight-week grid on recorded and approved time; the steps take the field's pace from it.
  const weeksRange = vectorRangeFor('weeks', todayYmd)
  let headline: Headline | null = null
  if (weeksInputs && vectorInputs) {
    const common = { zoom: 'weeks' as const, anchorYmd: weeksRange.end, todayYmd, people: vectorInputs.people, wages: vectorInputs.wages, sessions: weeksInputs.sessions, ratePerHourByJob: weeksInputs.ratePerHourByJob, assumedHalfJobs: weeksInputs.assumedHalfJobs, jobLabels: weeksInputs.jobLabels }
    headline = buildHeadline({ recorded: buildVectorGrid({ ...common, mode: 'recorded' }), approved: buildVectorGrid({ ...common, mode: 'approved' }) })
  }
  const fieldPace = weeksInputs ? fieldPaceByHours({ sessions: weeksInputs.sessions, ratePerHourByJob: weeksInputs.ratePerHourByJob, windowStart: data.windowStart, todayYmd, weeks }) : null

  // The five steps: Bill and Collect from the piles and the window's flows by day, as the page reads them.
  const sumWindow = (m: Map<string, number>): number => {
    let s = 0
    for (const [ymd, usd] of m) if (ymd >= data.windowStart && ymd <= todayYmd) s += usd
    return s
  }
  const billedPerWeek = sumWindow(data.invoicesSentByDay) / weeks
  const paidPerWeek = sumWindow(data.paymentsReceivedByDay) / weeks
  const late = receipts.filter((r) => r.basis === 'late')
  const lateCount = late.length + doubtful.length
  const held = thisWeekCall ? heldStageFor(thisWeekCall) : null
  const build = buildPace ? withFieldPaces(buildPace.stageInput, fieldPace?.earnedPerWeekUsd ?? null) : null
  const finishedPerWeek = fieldPace?.earnedPerWeekUsd ?? data.totals.earnedUsd / weeks
  const stageInput: StageFlowInput = {
    market: demand?.market ?? null,
    sales: demand ? { ...demand.sales, soldPerWeekUsd: buildPace?.soldPerWeekUsd ?? null } : null,
    fieldPerWeekUsd: build?.outPerWeekUsd ?? null,
    bill: billPile ? billStageInput(billPile, finishedPerWeek, billedPerWeek) : null,
    collect: collectDesk
      ? { pileUsd: collectDesk.pile.byState.late.usd + collectDesk.pile.byState.broken.usd + collectDesk.pile.byState.doubtful.usd, notDueUsd: collectDesk.pile.byState.notdue.usd + collectDesk.pile.byState.promised.usd, pileCount: collectDesk.pile.pastDueCount, inPerWeekUsd: billedPerWeek, outPerWeekUsd: paidPerWeek, lateCount: collectDesk.pile.pastDueCount }
      : fin
        ? { pileUsd: fin.ar.total, pileCount: fin.ar.count, inPerWeekUsd: billedPerWeek, outPerWeekUsd: paidPerWeek, lateCount }
        : null,
    build,
    heldLinkId: held,
    // The mail is built once the reads are in: a demand read that failed is a gap, not a loader in flight.
    demandLoading: false,
  }
  const stageFlow = buildStageFlow(stageInput)

  // Today's numbers behind the moves, which a recorded call reads again.
  const moveNumbers = {
    bill: billPile ? billPile.knownUsd : null,
    chase: late.reduce((s, r) => s + r.usd, 0) + doubtful.reduce((s, d) => s + d.usd, 0),
    approve: data.crew.pendingClosedHours,
    price: data.earned.noRevenueJobs.length,
    pct: data.earned.assumedHalfJobs.length,
  }
  const nowReading = {
    stageWeeks: Object.fromEntries(stageFlow.stages.map((s) => [s.id, s.weeks])) as Partial<Record<StageId, number | null>>,
    stagePilesUsd: Object.fromEntries(stageFlow.stages.map((s) => [s.id, s.pile.usd])) as Partial<Record<StageId, number | null>>,
    keys: moveNumbers,
  }

  const people = vectorInputs?.people ?? []
  const sends = vectorInputs?.invoiceSends ?? []
  const payments = vectorInputs?.payments ?? []
  const model = buildWeekCall({
    todayYmd,
    weekStart: thisWeek.start,
    headline,
    forecast,
    cashTodayUsd: cashToday,
    cashNote: accounts?.note ?? null,
    cashMayLead: WEEK_CASH_MAY_LEAD && bank != null,
    flow: stageFlow,
    picked: null,
    moveNumbers,
    counts: { billJobs: billPile?.knownJobs ?? null, lateInvoices: lateCount },
    // Nobody is signed in on a mail: the moves the page gives to whoever is looking go out with no person.
    people: { caller: '', biller: topPerson(sends, people, data.windowStart), collector: topPerson(payments, people, data.windowStart) },
    peopleIds: { caller: null, biller: topPersonId(sends, data.windowStart), collector: topPersonId(payments, data.windowStart) },
    marks: opts.marks,
    supplyDue: forecast ? (data.hazards.find((h) => h.ymd > todayYmd && h.ymd <= forecast.lowest.ymd) ?? null) : null,
    calls,
    now: nowReading,
    dayLabel: md,
  })
  const strip = buildFlowStrip(stageFlow, { market: todayPace(stageInput, 'market'), sales: todayPace(stageInput, 'sales'), build: todayPace(stageInput, 'build'), bill: todayPace(stageInput, 'bill'), collect: todayPace(stageInput, 'collect') })
  return { weekLabel: formatPayWeekLabel(thisWeek), todayLabel: md(todayYmd), model, strip, gaps: reads.gaps }
}
